script:
frappe.ui.form.on('Customer Subscription', {
    subscription_plan: function(frm) {
        if (frm.doc.subscription_plan) {
            frappe.db.get_value('Subscription Plan', frm.doc.subscription_plan, 'custom_number_of_deliveries', function(value) {
                frm.set_value('deliveries_included', value.custom_number_of_deliveries);
                frm.set_value('deliveries_remaining', value.custom_number_of_deliveries);
                frm.set_value('deliveries_used', 0);
            });
        }
    }
});
